<?php
session_start();require '../../config/db.php';if(!isset($_SESSION['admin_id'])){header('Location: ../../auth/login-admin.php');exit;}function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$q=trim($_GET['q']??'');$params=[];$where='';if($q!==''){$where='WHERE nome LIKE ? OR email LIKE ? OR telefone LIKE ?';$like='%'.$q.'%';$params=[$like,$like,$like];}$stmt=$pdo->prepare("SELECT c.*, (SELECT COUNT(*) FROM solicitacoes s WHERE s.cliente_id=c.id) total_chamados FROM clientes c $where ORDER BY c.nome ASC");$stmt->execute($params);$clientes=$stmt->fetchAll(PDO::FETCH_ASSOC);$success=$_SESSION['success_msg']??'';$error=$_SESSION['error_msg']??'';unset($_SESSION['success_msg'],$_SESSION['error_msg']);?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Clientes - Admin</title><link rel="stylesheet" href="../../assets/css/helpdesk-pro.css"></head><body><div class="hd-page"><header class="hd-topbar"><div class="hd-container hd-topbar-inner"><div class="hd-brand"><div class="hd-brand-icon">👥</div><div><h1>Clientes</h1><p>Gerencie dados, logo e chamados por cliente.</p></div></div><div class="hd-user"><a class="hd-chip" href="dashboard.php">Dashboard</a><a class="hd-chip" href="cadastrar-cliente.php">+ Cliente</a><a class="hd-chip" href="cofre-senhas.php">🔐 Cofre de Senhas</a><a class="hd-chip" href="../../auth/logout.php">Sair</a></div></div></header><main class="hd-main"><div class="hd-container"><?php if($success):?><div class="hd-alert hd-alert-success"><?=h($success)?></div><?php endif;?><?php if($error):?><div class="hd-alert hd-alert-error"><?=h($error)?></div><?php endif;?><section class="hd-card hd-card-pad"><div class="hd-section-head"><div><h2>Base de clientes</h2><p><?=count($clientes)?> cliente(s) encontrado(s).</p></div><a class="hd-btn hd-btn-primary" href="cadastrar-cliente.php">➕ Cadastrar cliente</a></div><form method="GET" class="hd-form-grid" style="margin-bottom:16px"><div class="hd-field"><label class="hd-label">Buscar cliente</label><input class="hd-input" name="q" value="<?=h($q)?>" placeholder="Nome, email ou telefone"></div><div class="hd-field"><label class="hd-label">Ação</label><button class="hd-btn hd-btn-primary" type="submit">🔎 Buscar</button></div></form><div class="hd-table-wrap"><table class="hd-table"><thead><tr><th>Cliente</th><th>Contato</th><th>Chamados</th><th>Cadastro</th><th>Ações</th></tr></thead><tbody><?php foreach($clientes as $c):?><tr><td><div class="hd-client-card"><div class="hd-client-avatar"><?php if(!empty($c['logo'])):?><img src="../../uploads/clientes/logos/<?=h(basename($c['logo']))?>" alt="Logo"><?php else:?><?=h(mb_strtoupper(mb_substr($c['nome'],0,1)))?><?php endif;?></div><div><strong><?=h($c['nome'])?></strong><br><span class="hd-ticket-meta">ID #<?=(int)$c['id']?></span></div></div></td><td><?=h($c['email'])?><br><span class="hd-ticket-meta"><?=h($c['telefone'])?></span></td><td><span class="hd-badge st-em-andamento"><?=(int)$c['total_chamados']?> chamados</span></td><td><span class="hd-ticket-meta"><?=!empty($c['criado_em'])?date('d/m/Y',strtotime($c['criado_em'])):'-'?></span></td><td><div class="hd-actions"><a class="hd-btn hd-btn-outline" href="editar-cliente.php?id=<?=(int)$c['id']?>">Editar</a><a class="hd-btn hd-btn-light" href="solicitacoes.php?id=<?=(int)$c['id']?>">Chamados</a><a class="hd-btn hd-btn-outline" href="financeiro.php?cliente_id=<?=(int)$c['id']?>">Financeiro</a></div></td></tr><?php endforeach;?><?php if(!$clientes):?><tr><td colspan="5"><div class="hd-empty">👥<strong>Nenhum cliente encontrado</strong></div></td></tr><?php endif;?></tbody></table></div></section></div></main></div><script>window.HD_CHAT_CONFIG={endpointBase:'../../controllers/',chatUrl:'mensagens.php'};</script><script src="../../assets/js/live-chat-alerts.js"></script></body></html>